username = #{username}, real_name = #{realName}, nickname = #{nickname}, phone = #{phone}, email = #{email}, password_hash = #{passwordHash}, password_changed_at = CURRENT_TIMESTAMP(3), status = #{status}, updated_at = CURRENT_TIMESTAMP(3)
